 export function matchRoute(pattern, path) {
-  if (pattern === path) return { matched: true, params: {} };
+  const patternSegments = toSegments(pattern);
+  const pathSegments = toSegments(path);
+  const params = {};
+
+  for (let i = 0; i < patternSegments.length; i += 1) {
+    const patternSegment = patternSegments[i];
+
+    if (isWildcardSegment(patternSegment)) {
+      const name = wildcardName(patternSegment);
+      const rest = pathSegments.slice(i).map(decodeSegment);
+      if (rest.includes(undefined)) return noMatch();
+      params[name] = rest.join('/');
+      return { matched: true, params };
+    }
+
+    if (i >= pathSegments.length) return noMatch();
+
+    const pathSegment = decodeSegment(pathSegments[i]);
+    if (pathSegment === undefined) return noMatch();
+
+    if (patternSegment.startsWith(':')) {
+      const name = patternSegment.slice(1);
+      if (!name) return noMatch();
+      params[name] = pathSegment;
+      continue;
+    }
+
+    const decodedPatternSegment = decodeSegment(patternSegment);
+    if (decodedPatternSegment === undefined || decodedPatternSegment !== pathSegment) {
+      return noMatch();
+    }
+  }
+
+  if (patternSegments.length !== pathSegments.length) return noMatch();
+  return { matched: true, params };
+}
+
+function noMatch() {
   return { matched: false, params: {} };
 }
+
+function toSegments(value) {
+  const normalized = normalizeTrailingSlash(value);
+  if (normalized === '/') return [];
+  return normalized.split('/').slice(normalized.startsWith('/') ? 1 : 0);
+}
+
+function normalizeTrailingSlash(value) {
+  if (value === '/') return value;
+  return value.replace(/\/+$/, '') || '/';
+}
+
+function decodeSegment(segment) {
+  try {
+    return decodeURIComponent(segment);
+  } catch {
+    return undefined;
+  }
+}
+
+function isWildcardSegment(segment) {
+  return segment === '*' || segment.startsWith('*') || (segment.startsWith(':') && segment.endsWith('*'));
+}
+
+function wildcardName(segment) {
+  if (segment === '*') return '*';
+  if (segment.startsWith('*')) return segment.slice(1) || '*';
+  return segment.slice(1, -1) || '*';
+}
