 test('matches named params', () => {
   assert.deepEqual(matchRoute('/users/:id', '/users/42'), { matched: true, params: { id: '42' } });
 });
+
+test('decodes URL encoded params and static segments', () => {
+  assert.deepEqual(matchRoute('/files/:name', '/files/report%202026'), {
+    matched: true,
+    params: { name: 'report 2026' },
+  });
+  assert.deepEqual(matchRoute('/search%20results/:term', '/search%20results/a%2Fb'), {
+    matched: true,
+    params: { term: 'a/b' },
+  });
+});
+
+test('matches wildcard rest segments', () => {
+  assert.deepEqual(matchRoute('/files/*rest', '/files/docs/2026/report.pdf'), {
+    matched: true,
+    params: { rest: 'docs/2026/report.pdf' },
+  });
+  assert.deepEqual(matchRoute('/assets/*', '/assets/icons/logo.svg'), {
+    matched: true,
+    params: { '*': 'icons/logo.svg' },
+  });
+});
+
+test('allows empty wildcard rest segments', () => {
+  assert.deepEqual(matchRoute('/files/*rest', '/files'), {
+    matched: true,
+    params: { rest: '' },
+  });
+});
+
+test('normalizes trailing slashes', () => {
+  assert.deepEqual(matchRoute('/users/:id/', '/users/42'), { matched: true, params: { id: '42' } });
+  assert.deepEqual(matchRoute('/users/:id', '/users/42/'), { matched: true, params: { id: '42' } });
+  assert.deepEqual(matchRoute('/', '/'), { matched: true, params: {} });
+});
+
+test('does not match missing or extra non-wildcard segments', () => {
+  assert.deepEqual(matchRoute('/users/:id', '/users'), { matched: false, params: {} });
+  assert.deepEqual(matchRoute('/users/:id', '/users/42/posts'), { matched: false, params: {} });
+});
+
+test('does not throw on malformed encoded segments', () => {
+  assert.deepEqual(matchRoute('/files/:name', '/files/%E0%A4%A'), { matched: false, params: {} });
+});
